document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('contact-form');if(!form)return;function clearErrors(){form.querySelectorAll('.is-invalid').forEach(el=>el.classList.remove('is-invalid'));form.querySelectorAll('.field-error-msg').forEach(el=>el.remove());const topAlert=form.closest('.col-lg-7')?.querySelector('.contact-alert');if(topAlert)topAlert.remove();}function showError(input,msg){input.classList.add('is-invalid');const div=document.createElement('div');div.className='invalid-feedback field-error-msg';div.textContent=msg;input.parentNode.appendChild(div);}function showTopAlert(){const col=form.closest('.col-lg-7');if(!col)return;const existing=col.querySelector('.contact-alert');if(existing)return;const alert=document.createElement('div');alert.className='contact-alert contact-alert-error';alert.innerHTML='<div class="contact-alert-icon"><i class="fa-solid fa-circle-xmark"></i></div><div class="contact-alert-text"><strong>\u064A\u0631\u062C\u0649 \u062A\u0639\u0628\u0626\u0629 \u062C\u0645\u064A\u0639 \u0627\u0644\u062D\u0642\u0648\u0644 \u0628\u0634\u0643\u0644 \u0635\u062D\u064A\u062D</strong></div>';col.insertBefore(alert,form.closest('.contact-card'));}form.addEventListener('submit',(event)=>{clearErrors();let hasError=false;const name=form.querySelector('[name=name]');const email=form.querySelector('[name=email]');const message=form.querySelector('[name=message]');const emailValue=email?.value.trim();if(!name?.value.trim()){showError(name,'\u0647\u0630\u0627 \u0627\u0644\u062D\u0642\u0644 \u0645\u0637\u0644\u0648\u0628');hasError=true;}if(!emailValue){showError(email,'\u0647\u0630\u0627 \u0627\u0644\u062D\u0642\u0644 \u0645\u0637\u0644\u0648\u0628');hasError=true;}else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailValue)){showError(email,'\u0623\u062F\u062E\u0644 \u0628\u0631\u064A\u062F\u0627\u064B \u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A\u0627\u064B \u0635\u0627\u0644\u062D\u0627\u064B');hasError=true;}if(!message?.value.trim()){showError(message,'\u0647\u0630\u0627 \u0627\u0644\u062D\u0642\u0644 \u0645\u0637\u0644\u0648\u0628');hasError=true;}if(hasError){event.preventDefault();showTopAlert();return false;}const btn=form.querySelector('[type=submit]');if(btn){btn.disabled=true;btn.innerHTML='<i class="fas fa-spinner fa-spin ms-2"></i> \u062C\u0627\u0631\u064A \u0627\u0644\u0625\u0631\u0633\u0627\u0644...';}return true;});});